def regex_search(pattern: str, text: str) -> bool:
    # --- AST node types ---
    class _Lit:
        __slots__ = ('ch',)
        def __init__(self, ch): self.ch = ch
    class _Any: pass
    class _Class:
        __slots__ = ('chars', 'neg')
        def __init__(self, chars, neg): self.chars = chars; self.neg = neg
    class _Anchor:
        __slots__ = ('kind',)
        def __init__(self, kind): self.kind = kind
    class _Group:
        __slots__ = ('body',)
        def __init__(self, body): self.body = body
    class _Repeat:
        __slots__ = ('body', 'quant')
        def __init__(self, body, quant): self.body = body; self.quant = quant
    class _Seq:
        __slots__ = ('items',)
        def __init__(self, items): self.items = items
    class _Alt:
        __slots__ = ('left', 'right')
        def __init__(self, left, right): self.left = left; self.right = right

    # --- Parser ---
    def _parse(pat):
        pos = 0

        def choice():
            left = seq()
            while pos < len(pat) and pat[pos] == '|':
                pos += 1
                right = seq()
                left = _Alt(left, right)
            return left

        def seq():
            items = []
            while pos < len(pat) and pat[pos] not in ('|', ')'):
                items.append(quantified())
            if not items:
                return None
            if len(items) == 1:
                return items[0]
            return _Seq(items)

        def quantified():
            nonlocal pos
            atom = atom()
            if pos < len(pat) and pat[pos] in ('*', '+', '?'):
                if isinstance(atom, _Anchor):
                    raise ValueError
                q = pat[pos]
                pos += 1
                return _Repeat(atom, q)
            return atom

        def atom():
            nonlocal pos
            if pos >= len(pat):
                raise ValueError
            c = pat[pos]
            if c == '(':
                pos += 1
                body = choice()
                if pos >= len(pat) or pat[pos] != ')':
                    raise ValueError
                pos += 1
                return _Group(body)
            if c == '[':
                return charclass()
            if c == '.':
                pos += 1
                return _Any()
            if c == '\\':
                if pos + 1 >= len(pat):
                    raise ValueError
                pos += 1
                ch = pat[pos]
                pos += 1
                return _Lit(ch)
            if c == '^':
                pos += 1
                return _Anchor('^')
            if c == '$':
                pos += 1
                return _Anchor('$')
            if c in ('*', '+', '?', ')', '|'):
                raise ValueError
            pos += 1
            return _Lit(c)

        def charclass():
            nonlocal pos
            pos += 1  # skip [
            neg = False
            if pos < len(pat) and pat[pos] == '^':
                neg = True
                pos += 1
            chars = set()
            while pos < len(pat) and pat[pos] != ']':
                if pat[pos] == '\\':
                    if pos + 1 >= len(pat):
                        raise ValueError
                    c1 = pat[pos + 1]
                    pos += 2
                else:
                    c1 = pat[pos]
                    pos += 1
                if (pos < len(pat) and pat[pos] == '-'
                        and pos + 1 < len(pat) and pat[pos + 1] != ']'):
                    pos += 1  # skip -
                    if pos < len(pat) and pat[pos] == '\\':
                        if pos + 1 >= len(pat):
                            raise ValueError
                        c2 = pat[pos + 1]
                        pos += 2
                    else:
                        c2 = pat[pos]
                        pos += 1
                    if ord(c1) > ord(c2):
                        raise ValueError
                    for cp in range(ord(c1), ord(c2) + 1):
                        chars.add(chr(cp))
                else:
                    chars.add(c1)
            if pos >= len(pat):
                raise ValueError
            pos += 1  # skip ]
            if not chars:
                raise ValueError
            return _Class(frozenset(chars), neg)

        node = choice()
        if pos != len(pat):
            raise ValueError
        return node

    # --- NFA construction ---
    edges = []

    def new_state():
        edges.append([])
        return len(edges) - 1

    def add(src, edge):
        edges[src].append(edge)

    def build(node):
        if node is None:
            s = new_state(); e = new_state()
            add(s, ('eps', e))
            return s, e
        if isinstance(node, _Lit):
            s = new_state(); e = new_state()
            add(s, ('lit', node.ch, e))
            return s, e
        if isinstance(node, _Any):
            s = new_state(); e = new_state()
            add(s, ('any', e))
            return s, e
        if isinstance(node, _Class):
            s = new_state(); e = new_state()
            add(s, ('class', node.chars, node.neg, e))
            return s, e
        if isinstance(node, _Anchor):
            s = new_state(); e = new_state()
            add(s, ('start_assert', e) if node.kind == '^' else ('end_assert', e))
            return s, e
        if isinstance(node, _Group):
            return build(node.body)
        if isinstance(node, _Seq):
            frags = [build(it) for it in node.items]
            for i in range(len(frags) - 1):
                add(frags[i][1], ('eps', frags[i + 1][0]))
            return frags[0][0], frags[-1][1]
        if isinstance(node, _Alt):
            ls, le = build(node.left)
            rs, re_ = build(node.right)
            s = new_state(); e = new_state()
            add(s, ('eps', ls)); add(s, ('eps', rs))
            add(le, ('eps', e)); add(re_, ('eps', e))
            return s, e
        if isinstance(node, _Repeat):
            bs, be = build(node.body)
            s = new_state(); e = new_state()
            if node.quant == '*':
                add(s, ('eps', bs)); add(be, ('eps', bs))
                add(be, ('eps', e)); add(s, ('eps', e))
            elif node.quant == '+':
                add(s, ('eps', bs)); add(be, ('eps', bs))
                add(be, ('eps', e))
            else:
                add(s, ('eps', bs)); add(be, ('eps', e))
                add(s, ('eps', e))
            return s, e

    start, end = build(_parse(pattern))

    # --- NFA simulation ---
    text_len = len(text)

    def closure(states, pos):
        result = set()
        stack = list(states)
        while stack:
            s = stack.pop()
            if s in result:
                continue
            result.add(s)
            for edge in edges[s]:
                typ = edge[0]
                if typ == 'eps':
                    t = edge[1]
                    if t not in result:
                        stack.append(t)
                elif typ == 'start_assert':
                    if pos == 0:
                        t = edge[1]
                        if t not in result:
                            stack.append(t)
                elif typ == 'end_assert':
                    if pos == text_len:
                        t = edge[1]
                        if t not in result:
                            stack.append(t)
        return result

    current = closure({start}, 0)
    if end in current:
        return True
    for i in range(text_len):
        ch = text[i]
        nxt = set()
        for s in current:
            for edge in edges[s]:
                typ = edge[0]
                if typ == 'lit':
                    if edge[1] == ch:
                        nxt.add(edge[2])
                elif typ == 'any':
                    nxt.add(edge[1])
                elif typ == 'class':
                    chars, neg, tgt = edge[1], edge[2], edge[3]
                    if (ch in chars) != neg:
                        nxt.add(tgt)
        current = closure(nxt, i + 1)
        if end in current:
            return True
    return False
